import { CHAIN, CONTRACTS } from './chain-config.js';
import { writePlayerStorage } from './browser-storage.js';

// Tiny completion identities, never reward payloads. An unfinished multi-part
// receipt can resume after closing/reloading without replaying its shown parts.
export const REVEAL_CHECKPOINT_PREFIX = `degenerus:reveal-checkpoints:v1:${CHAIN.id}:${String(CONTRACTS.GAME).toLowerCase()}:`;
const memory = new Map();
function keyFor(address) {
  return /^0x[\da-f]{40}$/i.test(address || '')
    ? `${REVEAL_CHECKPOINT_PREFIX}${address.toLowerCase()}` : null;
}
function read(key) {
  try {
    const value = JSON.parse(globalThis.localStorage?.getItem(key) || '[]');
    return Array.isArray(value) ? value.filter(id => typeof id === 'string') : [];
  } catch { return []; }
}
function entries(key) {
  if (!memory.has(key)) memory.set(key, new Set(read(key)));
  return memory.get(key);
}
export function hasRevealCheckpoint(address, id) {
  const key = keyFor(address);
  return Boolean(key && id && entries(key).has(id));
}
export function markRevealCheckpoint(address, id) {
  const key = keyFor(address);
  if (!key || !id) return;
  const saved = entries(key);
  if (saved.has(id)) return;
  for (const prior of read(key)) saved.add(prior);
  saved.add(id);
  writePlayerStorage(key, JSON.stringify([...saved]));
}
globalThis.addEventListener?.('storage', event => {
  if (event.key?.startsWith(REVEAL_CHECKPOINT_PREFIX)) {
    for (const id of read(event.key)) entries(event.key).add(id);
  }
});
export function __resetRevealCheckpointsForTest() { memory.clear(); }
